// SecPlus Academy acronym glossary. Every acronym used in the lessons, deep dives, and cheat sheet, plus those in questions.
// Rendered by the engine as hover links in tutorials and the cheat sheet (tip on hover, more on click) and as the
// cheat sheet's Acronyms section. Keys are matched as whole words, case-sensitive, plurals allowed. Original wording.
// Fields: full (what it stands for), tip (one sentence for the tooltip), more (the longer explanation; blank line = new paragraph).
window.FRA = window.FRA || {};
FRA.acronyms = {
  "3DES": { full: "Triple Data Encryption Standard", tip: "DES applied three times; legacy and slow, replaced by AES.", more: "3DES stretched the old 56-bit DES cipher by running it three times with different keys. It is much slower than AES and now deprecated, seen only in legacy payment and banking systems." },
  "802.1X": { full: "IEEE 802.1X", tip: "Port-based network access control: a device must authenticate before the switch port or Wi-Fi passes traffic.", more: "With 802.1X the client (supplicant) presents credentials or a certificate through the switch or access point (authenticator) to a RADIUS server (authentication server) using EAP. Until it succeeds, the port only passes authentication traffic. It is the basis of WPA2 and WPA3 Enterprise and of wired NAC." },
  "AAA": { full: "Authentication, authorization, and accounting", tip: "Prove who you are, decide what you may do, record what you did.", more: "Authentication verifies identity (password, token, certificate), authorization decides which resources or commands are allowed, and accounting logs the session for auditing. RADIUS and TACACS+ are the protocols that deliver AAA to network devices." },
  "ABAC": { full: "Attribute-based access control", tip: "Access decisions based on attributes of the user, resource, and context, such as time and location.", more: "ABAC policies can say a manager may open records from the office during business hours. It is more flexible than roles and underlies many cloud and zero trust policies." },
  "ACL": { full: "Access control list", tip: "An ordered list of permit and deny rules on a router, firewall, or file system.", more: "On network devices an ACL filters packets by source, destination, protocol, and port, processed top down with the first match winning and an implicit deny at the end. On file systems an ACL lists which users and groups have which permissions on an object." },
  "AES": { full: "Advanced Encryption Standard", tip: "The standard symmetric cipher, with 128, 192, or 256-bit keys.", more: "AES encrypts and decrypts with the same key and is fast enough to protect disks, Wi-Fi (WPA2 and WPA3), VPNs, and TLS sessions. AES-128 is secure; AES-256 is used for high-value data. It replaced DES and 3DES." },
  "AES-128": { full: "AES with a 128-bit key", tip: "The standard-strength AES, secure and fast.", more: "A 128-bit key has more combinations than any brute-force attack can try. AES-128 is the everyday choice; AES-256 adds margin against future advances." },
  "AES-256": { full: "AES with a 256-bit key", tip: "The high-strength AES used for data at rest and sensitive sessions.", more: "AES-256 doubles the key length of AES-128 for a larger security margin at a small speed cost. It is the common choice for full-disk encryption and government data." },
  "AES-CCMP": { full: "AES in CCMP mode", tip: "The AES-based encryption WPA2 uses for Wi-Fi.", more: "CCMP is the mode that gives WPA2 both confidentiality and integrity with AES. When a question contrasts WPA2-AES with WPA-TKIP, this is what it means." },
  "AH": { full: "Authentication Header", tip: "The IPsec protocol that provides integrity and authentication without encryption.", more: "AH signs the packet, including parts of the header, so it cannot be altered, but leaves the contents readable. Because it covers header fields, it breaks under NAT. It is IP protocol 51 and is rarely used alone today; ESP does both jobs." },
  "ALE": { full: "Annualized loss expectancy", tip: "The expected yearly cost of a risk: SLE times ARO.", more: "ALE is the number that justifies spending. If a control costs less per year than the ALE it prevents, it is worth buying. Exam math questions give asset value, exposure factor, and rate and ask for ALE." },
  "AP": { full: "Access point", tip: "The radio that bridges Wi-Fi clients onto the wired network.", more: "An access point turns Wi-Fi frames into Ethernet frames and back. Standalone (autonomous) APs are configured one by one; lightweight APs are managed by a wireless LAN controller. Each AP advertises one or more SSIDs, and clients roam between APs that share an SSID. In the CBET course the same letters also appear in anteroposterior X-ray views; read the context." },
  "API": { full: "Application programming interface", tip: "The defined way one program talks to another, such as the web endpoints a cloud service exposes.", more: "APIs let software request data and actions from other software. Cloud consoles, SDN controllers, and mobile apps all work through APIs. Security concerns include stolen API keys, missing authentication, and rate limiting." },
  "APT": { full: "Advanced persistent threat", tip: "A well-funded, skilled, patient attacker, usually a nation-state, that stays hidden for a long time.", more: "APTs pursue long-term goals such as espionage, using custom malware and quiet lateral movement. The exam cue is nation-state, sophisticated, and persistent." },
  "ARO": { full: "Annualized rate of occurrence", tip: "How many times per year an incident is expected to happen.", more: "An ARO of 0.5 means once every two years; 12 means monthly. It is estimated from history and threat intelligence and multiplies SLE to give ALE." },
  "ARP": { full: "Address Resolution Protocol", tip: "Finds the MAC address that goes with a known IPv4 address on the local segment.", more: "When a host knows the IP address of a neighbor but not its MAC address, it broadcasts an ARP request and the owner replies with its MAC. Hosts cache the answer in an ARP table. Because ARP has no authentication, attackers can poison the cache to redirect traffic, which is why switches offer dynamic ARP inspection. IPv6 replaces ARP with Neighbor Discovery." },
  "ASLR": { full: "Address space layout randomization", tip: "Randomizes where programs load in memory so exploits cannot predict addresses.", more: "ASLR is an operating system defense that makes memory corruption exploits unreliable by moving code and data to random locations each run." },
  "AUP": { full: "Acceptable use policy", tip: "The rules for how staff may use company systems and data.", more: "The AUP tells employees what is allowed on company devices and networks and what monitoring to expect. Signing it is usually part of onboarding." },
  "AV": { full: "Asset value, or antivirus", tip: "In risk math, what an asset is worth; in endpoint security, antivirus software.", more: "Asset value times exposure factor gives the single loss expectancy. Antivirus scans files and behavior for known malware and is now part of endpoint detection and response." },
  "BEC": { full: "Business email compromise", tip: "Fraud by email impersonating an executive or vendor to redirect payments.", more: "The attacker spoofs or hijacks a trusted mailbox and asks finance to wire money or change bank details. It is social engineering, not malware, so the defenses are verification procedures and DMARC." },
  "BIA": { full: "Business impact analysis", tip: "Identifies critical functions and what an outage of each would cost, setting RTO and RPO.", more: "The BIA ranks systems by how much their loss would hurt and how fast they must return. Its outputs, recovery time and recovery point objectives, drive the disaster recovery design." },
  "BPA": { full: "Business partnership agreement", tip: "How partners share responsibilities, profits, and liabilities.", more: "A BPA is the contract between organizations that go into business together, covering decisions, money, and what happens if one leaves." },
  "BYOD": { full: "Bring your own device", tip: "Staff use personal phones and laptops for work.", more: "BYOD saves the company money but mixes personal and corporate data on devices the company does not control. Mobile device management, containerization, and acceptable use policies define what the company may do on the device and what happens when someone leaves." },
  "CA": { full: "Certificate authority", tip: "The trusted entity that signs certificates.", more: "A CA verifies that an applicant controls a name or identity and then signs a certificate binding that identity to a public key. Devices ship with a list of trusted root CAs; anything they signed, directly or through intermediates, is trusted. A certificate from an unknown CA produces the browser warning." },
  "CEO": { full: "Chief executive officer", tip: "The top executive; the person impersonated in whaling and business email compromise.", more: "Attacks that pose as the CEO exploit staff reluctance to question authority. Verification procedures for payment changes are the defense." },
  "CFO": { full: "Chief financial officer", tip: "The executive in charge of money; a common target and impersonation in payment fraud.", more: "An email from the CFO asking to wire funds to a new account is the classic business email compromise scenario." },
  "CI": { full: "Continuous integration", tip: "Every code change is automatically built and tested when it is committed.", more: "CI pipelines compile code, run tests, and often run security scans on each commit, catching problems early. Paired with continuous deployment, it pushes approved changes to production automatically." },
  "CIA": { full: "Confidentiality, integrity, and availability", tip: "The three goals of security: keep data secret, keep it correct, keep it reachable.", more: "Confidentiality means only authorized people can read data (encryption, access control). Integrity means it has not been altered (hashes, signatures). Availability means systems are up when needed (redundancy, backups). Every attack and every control on the exam maps to one or more of the three; ransomware, for instance, attacks availability." },
  "CIS": { full: "Center for Internet Security", tip: "The organization that publishes hardening benchmarks and the CIS Controls.", more: "CIS Benchmarks are detailed secure configuration guides for operating systems, cloud services, and applications; compliance scanners check systems against them." },
  "COPE": { full: "Corporate-owned, personally enabled", tip: "The company buys the device and lets staff use it personally.", more: "COPE gives the organization full control of the device while allowing personal use. It sits between BYOD (personal device) and fully locked corporate devices." },
  "CPU": { full: "Central processing unit", tip: "The processor that executes instructions.", more: "The CPU's cores, threads, clock speed, and cache set a computer's performance. Sudden CPU spikes are a security indicator for crypto mining or malware. In the A+ course you match its socket (LGA, PGA, AM4, AM5) to the motherboard and keep it cool." },
  "CRL": { full: "Certificate revocation list", tip: "A signed list of revoked certificate serial numbers published by a CA.", more: "Clients download the CRL to check whether a certificate was revoked before it expired, for example because its key was stolen. CRLs grow large and update slowly, which is why OCSP exists." },
  "CSR": { full: "Certificate signing request", tip: "The file containing a public key and identity that you send to a CA to get a certificate.", more: "You generate a key pair, put the public key and the subject details into a CSR, and the certificate authority signs it into a certificate. The private key never leaves your server." },
  "CSRF": { full: "Cross-site request forgery", tip: "Tricks a logged-in user's browser into sending a request the user did not intend.", more: "A CSRF attack makes the victim's browser submit a form or link to a site where they are already authenticated, such as changing an email address. Anti-forgery tokens and same-site cookies defeat it." },
  "CVE": { full: "Common Vulnerabilities and Exposures", tip: "The public identifier for a known vulnerability, such as CVE-2024-12345.", more: "CVE numbers let vendors, scanners, and advisories refer to the same flaw. A vulnerability scanner reports CVEs; the CVSS score tells you how severe each one is." },
  "CVSS": { full: "Common Vulnerability Scoring System", tip: "A 0 to 10 severity score for a vulnerability.", more: "CVSS rates exploitability and impact into a base score: 9 and above critical, 7 to 8.9 high, 4 to 6.9 medium. It helps prioritize patching, though environmental context matters too." },
  "CYOD": { full: "Choose your own device", tip: "Staff pick from a list of approved devices the company then owns and manages.", more: "CYOD balances user preference with manageability: the company supports only the approved models but employees get a choice." },
  "DAC": { full: "Discretionary access control", tip: "The owner of a resource decides who may access it.", more: "In discretionary access control the file's owner sets permissions, as in Windows and Linux file systems. It is flexible but depends on every owner making good choices. Mandatory access control, by contrast, enforces labels the owner cannot override." },
  "DBA": { full: "Database administrator", tip: "The person who runs the database servers.", more: "On the exam the DBA appears in separation-of-duties scenarios, for example encrypting a column with a key the DBA does not hold." },
  "DDoS": { full: "Distributed denial of service", tip: "Many sources, usually a botnet, flood a target at once.", more: "DDoS attacks use thousands of compromised machines, or amplification through open DNS and NTP servers, to overwhelm a target. Defenses are upstream scrubbing services, CDNs, and rate limiting." },
  "DER": { full: "Distinguished Encoding Rules", tip: "The binary format for certificates and keys.", more: "DER is the raw binary encoding of a certificate; PEM is DER wrapped in Base64. Windows often uses .cer or .der files in this form." },
  "DES": { full: "Data Encryption Standard", tip: "The 1970s 56-bit block cipher; broken by brute force, do not use.", more: "DES's key is short enough to be searched exhaustively in hours. Recognize it as legacy on the exam and never recommend it." },
  "DHCP": { full: "Dynamic Host Configuration Protocol", tip: "Hands out IP addresses, masks, gateways, and DNS servers automatically (UDP 67 and 68).", more: "A DHCP server leases addresses to clients through the DORA exchange: Discover, Offer, Request, Acknowledge. The lease also carries the subnet mask, default gateway, DNS servers, and options such as a TFTP server. Because Discover is a broadcast, a router needs a relay (IP helper) to reach a server on another subnet. Reservations tie a fixed address to a MAC; scopes and exclusions define the pool." },
  "DKIM": { full: "DomainKeys Identified Mail", tip: "Outgoing mail is digitally signed; the public key is published in DNS.", more: "DKIM lets a receiving server verify that a message really came from the domain and was not altered, by checking the signature against the key in a DNS TXT record." },
  "DLP": { full: "Data loss prevention", tip: "Tools that detect and block sensitive data leaving by email, web, USB, or cloud.", more: "DLP inspects content for patterns such as card numbers or classification labels and blocks or logs the transfer. It works on endpoints, email gateways, and cloud services. Files copied to USB drives being blocked is DLP." },
  "DMARC": { full: "Domain-based Message Authentication, Reporting, and Conformance", tip: "A DNS policy telling receivers what to do with mail that fails SPF or DKIM, and where to send reports.", more: "DMARC ties SPF and DKIM to the visible From address and states a policy: none, quarantine, or reject. Reports show who is sending mail as your domain." },
  "DMZ": { full: "Demilitarized zone", tip: "A screened subnet between the internet and the internal network for public-facing servers.", more: "A DMZ holds web, mail, and other servers that outsiders must reach. Firewalls allow the internet to reach the DMZ, and tightly restrict the DMZ's access to the inside, so a compromised public server does not give an attacker the internal LAN. The modern term is screened subnet." },
  "DNS": { full: "Domain Name System", tip: "Translates names such as www.example.com into IP addresses (UDP 53, TCP 53 for zone transfers).", more: "DNS is a distributed database of names. A resolver asks recursive servers, which walk from the root to the top-level domain to the authoritative server for the zone. Record types include A (IPv4), AAAA (IPv6), CNAME (alias), MX (mail), PTR (reverse), TXT (text such as SPF), SRV (service location), NS, and SOA. If a site works by IP address but not by name, DNS is the problem." },
  "DNSSEC": { full: "DNS Security Extensions", tip: "Digital signatures on DNS records so a resolver can tell an answer was not forged.", more: "DNSSEC adds signature records to a zone and a chain of trust from the root down. A validating resolver checks the signatures and rejects tampered or spoofed answers. It provides integrity and authenticity, not privacy: queries are still readable on the wire, which is what DoT and DoH address." },
  "DoH": { full: "DNS over HTTPS", tip: "DNS queries carried inside HTTPS on TCP 443 so they cannot be read or altered in transit.", more: "DoH wraps DNS inside an ordinary HTTPS connection to a resolver. Browsers and operating systems support it, and because it looks like web traffic it is hard for a network to block or inspect. It protects privacy between the client and the resolver; it does not sign the records themselves." },
  "DoS": { full: "Denial of service", tip: "One source floods or crashes a target so it cannot serve users.", more: "A DoS attack exhausts bandwidth, connections, or CPU. Because it comes from one source it can be filtered; distributed attacks from many sources are far harder." },
  "DoT": { full: "DNS over TLS", tip: "DNS queries encrypted with TLS on TCP 853.", more: "DoT sends DNS over a dedicated TLS connection on port 853. Like DoH it hides queries from anyone on the path, but using its own port makes it easier to identify and manage on a corporate network." },
  "DSA": { full: "Digital Signature Algorithm", tip: "A government-standard signature algorithm; used less than RSA and ECDSA today.", more: "DSA signs but does not encrypt. It appears on the exam as one of the signature algorithms alongside RSA and ECDSA." },
  "EAP": { full: "Extensible Authentication Protocol", tip: "The framework that carries authentication methods inside 802.1X.", more: "EAP defines how credentials travel between the supplicant and the authentication server; the method (EAP-TLS, PEAP, EAP-TTLS, EAP-FAST) decides what proof is used." },
  "EAP-FAST": { full: "EAP Flexible Authentication via Secure Tunneling", tip: "Cisco's tunneled EAP method using a protected access credential instead of a certificate.", more: "EAP-FAST builds its tunnel from a pre-provisioned credential rather than a server certificate. It is mostly seen in Cisco environments." },
  "EAP-TLS": { full: "EAP with Transport Layer Security", tip: "Certificate-based authentication on both sides; the strongest Wi-Fi and wired 802.1X method.", more: "EAP-TLS requires a certificate on every client as well as the server, so there is no password to phish. It is the gold standard for enterprise wireless." },
  "EAP-TTLS": { full: "EAP with Tunneled TLS", tip: "A server certificate builds a TLS tunnel, then the client authenticates inside it with a password or other method.", more: "EAP-TTLS needs only a server certificate and can carry legacy password methods safely inside the tunnel." },
  "ECC": { full: "Elliptic curve cryptography", tip: "Public-key cryptography that gives RSA-level strength with much shorter keys, ideal for phones and IoT.", more: "ECC builds key pairs on elliptic curve math. A 256-bit ECC key is roughly as strong as a 3072-bit RSA key, so it is faster and uses less power. ECDSA signs and ECDHE exchanges keys. In the A+ course ECC means error-correcting code memory." },
  "ECDHE": { full: "Elliptic Curve Diffie-Hellman Ephemeral", tip: "Key exchange with a fresh elliptic curve key per session, giving forward secrecy.", more: "ECDHE lets two parties agree a session key over an open channel. Because the keys are ephemeral, a later compromise of the server's long-term key cannot decrypt recorded sessions. TLS 1.3 requires ephemeral exchanges." },
  "ECDSA": { full: "Elliptic Curve Digital Signature Algorithm", tip: "Digital signatures using elliptic curve keys.", more: "ECDSA is the signature counterpart of RSA for elliptic curve keys, used in TLS certificates, code signing, and cryptocurrency. It is fast and its signatures are small." },
  "EDR": { full: "Endpoint detection and response", tip: "Endpoint agents that record activity, detect attacks, and let responders isolate and clean the machine.", more: "EDR goes beyond antivirus by watching process behavior, collecting telemetry, and giving analysts tools to investigate and contain a compromised host remotely." },
  "EF": { full: "Exposure factor", tip: "The fraction of an asset's value lost in one incident.", more: "If a flood would destroy 40 percent of a warehouse's value, the exposure factor is 0.4. Asset value times exposure factor gives the single loss expectancy." },
  "ESP": { full: "Encapsulating Security Payload", tip: "The IPsec protocol that encrypts and authenticates the payload.", more: "ESP provides confidentiality, integrity, and authentication for IPsec traffic and is what nearly every VPN uses. It is IP protocol 50. In tunnel mode the original packet is encrypted inside a new one." },
  "FIDO2": { full: "Fast Identity Online 2", tip: "Passwordless or second-factor authentication with a hardware security key or device biometrics.", more: "FIDO2 uses public-key cryptography so the server stores only a public key; phishing sites cannot capture anything reusable. Security keys and platform authenticators such as Windows Hello implement it." },
  "FIM": { full: "File integrity monitoring", tip: "Alerts when critical files or configurations change.", more: "FIM hashes important files and reports any unexpected change, catching tampering with system binaries, web content, or configuration. It is required by standards such as PCI DSS." },
  "FTP": { full: "File Transfer Protocol", tip: "Plaintext file transfer on TCP 21 (control) and 20 (data); replace with SFTP or FTPS.", more: "FTP sends usernames, passwords, and files in the clear and needs a second connection for data, which complicates firewalls. Active mode has the server connect back to the client; passive mode has the client open both. It survives on legacy systems only." },
  "FTPS": { full: "FTP Secure", tip: "FTP wrapped in TLS, ports 990 and 989 (implicit) or 21 with an upgrade (explicit).", more: "FTPS adds TLS encryption to ordinary FTP. It is different from SFTP, which runs over SSH. Exam questions test whether you know they are separate protocols on separate ports." },
  "GB": { full: "Gigabyte", tip: "About a billion bytes; the unit for RAM, storage, and data caps.", more: "A gigabyte is 1,000 or 1,024 megabytes depending on whether the maker counts in decimal or binary. RAM is sold in GB, and 32-bit systems can address only about 4 GB." },
  "GCMP": { full: "Galois/Counter Mode Protocol", tip: "The stronger AES encryption mode used by WPA3.", more: "GCMP replaces CCMP in WPA3, especially in Enterprise 192-bit mode, providing authenticated encryption with better performance." },
  "GPS": { full: "Global Positioning System", tip: "Satellite positioning, also used as a stratum 0 time reference.", more: "GPS receivers get both position and extremely accurate time from satellites. Networks use GPS-disciplined clocks as their top-level NTP or PTP reference. Phones use GPS for location, which is also the somewhere-you-are factor in authentication." },
  "HMAC": { full: "Hash-based message authentication code", tip: "A keyed hash that proves a message came from someone with the key and was not altered.", more: "HMAC combines a secret key with a hash such as SHA-256. Only holders of the key can produce or verify the code, giving integrity and authenticity without a public-key signature. It is used in TLS, API authentication, and time-based one-time passwords." },
  "HR": { full: "Human resources", tip: "The department that hires and separates staff; its system should drive account provisioning and removal.", more: "Tying account creation and deprovisioning to HR records closes the gap where former employees keep access." },
  "HSM": { full: "Hardware security module", tip: "A tamper-resistant appliance or card that generates, stores, and uses cryptographic keys.", more: "An HSM performs signing and encryption inside protected hardware so private keys are never exposed, even to administrators. Certificate authorities, payment systems, and cloud key services use them. In the A+ course an HSM header on a motherboard connects such a module." },
  "HTTP": { full: "Hypertext Transfer Protocol", tip: "Web traffic in the clear on TCP 80.", more: "HTTP carries web pages and API calls without encryption, so anything sent can be read on the path. HTTPS on 443 is the secure form, and modern sites redirect to it." },
  "HTTPS": { full: "Hypertext Transfer Protocol Secure", tip: "HTTP inside TLS on TCP 443.", more: "HTTPS encrypts web traffic and lets the browser verify the server's certificate. The padlock means the connection to that server is private, not that the site is honest. DoH also rides on 443." },
  "IaaS": { full: "Infrastructure as a service", tip: "The provider supplies virtual machines, storage, and networks; you manage the operating system and up.", more: "IaaS rents raw computing. You install and patch the OS and applications while the provider runs the hardware. The exam cue is you manage the OS, they manage the hardware." },
  "IaC": { full: "Infrastructure as code", tip: "Defining networks and servers in files that tools build automatically and repeatably.", more: "With IaC the configuration lives in version-controlled text, and a tool applies it, so environments are consistent and changes are reviewed like software. Drift between the files and reality is detected rather than accumulated." },
  "ICS": { full: "Industrial control system", tip: "The general term for computers that run physical processes; SCADA is one kind.", more: "ICS covers programmable logic controllers, distributed control systems, and SCADA. Their priorities are safety and availability, so security must come from segmentation and monitoring rather than frequent patching." },
  "ID": { full: "Identifier or identification", tip: "A name or number that uniquely labels a user, device, session, or record.", more: "IDs appear everywhere: user IDs, VLAN IDs, process IDs, patient IDs, and caller ID, which can be spoofed. The exam mostly tests that an ID by itself is not proof of identity." },
  "IDS": { full: "Intrusion detection system", tip: "Watches a copy of the traffic and alerts on attacks; cannot block them.", more: "An IDS sits out of band, usually on a SPAN port or tap, and compares traffic against signatures and behavior baselines. It detects and reports but does not stop anything. A host-based IDS does the same on one machine's logs and files." },
  "IKE": { full: "Internet Key Exchange", tip: "Negotiates the keys and security associations for IPsec; UDP 500, and 4500 through NAT.", more: "IKE authenticates the two ends of a VPN with pre-shared keys or certificates and agrees the encryption keys for ESP. IKEv2 is the current version. NAT traversal moves it to UDP 4500 so it survives address translation." },
  "IMAP": { full: "Internet Message Access Protocol", tip: "Reads mail that stays on the server, synced across devices; TCP 143, secure 993.", more: "IMAP leaves messages on the server and mirrors folders and read status to every client, which is what phones and laptops need. It replaced POP3 for most users." },
  "IMAPS": { full: "IMAP Secure", tip: "IMAP over TLS on TCP 993.", more: "IMAPS encrypts the connection between a mail client and server. It is the port to allow when a question asks for secure mail retrieval." },
  "iOS": { full: "iPhone operating system", tip: "Apple's mobile operating system for iPhone.", more: "iOS is tightly controlled: apps come from the App Store and are sandboxed. Jailbreaking removes those restrictions and the protection that comes with them. iPadOS is the tablet variant." },
  "IoT": { full: "Internet of Things", tip: "Networked devices such as cameras, sensors, thermostats, and smart TVs.", more: "IoT devices are small computers with limited security: default passwords, rare patches, and long lifetimes. They belong on their own segmented network with access limited to what they need." },
  "IP": { full: "Internet Protocol", tip: "The Layer 3 protocol that addresses and routes packets between networks.", more: "IP gives every host a logical address and lets routers forward packets from network to network using that address. Version 4 uses 32-bit addresses written as four numbers; version 6 uses 128-bit addresses written in hex. IP itself is best effort: it does not guarantee delivery, which is why TCP exists above it." },
  "IPS": { full: "Intrusion prevention system", tip: "Sits inline and blocks attacks as they pass.", more: "An IPS is an IDS placed in the traffic path so it can drop malicious packets and reset connections. Being inline means it can also block legitimate traffic if a signature is wrong or it fails closed. In the A+ course the same letters name in-plane switching LCD panels; read the context." },
  "IPsec": { full: "Internet Protocol Security", tip: "The suite that encrypts and authenticates IP packets for VPNs.", more: "IPsec uses AH for integrity, ESP for encryption plus integrity, and IKE to negotiate keys. Transport mode protects the payload between two hosts; tunnel mode wraps the whole packet for site-to-site VPNs. ESP is IP protocol 50, AH is 51, IKE uses UDP 500 and 4500 for NAT traversal." },
  "ISAC": { full: "Information sharing and analysis center", tip: "An industry group where members share threat intelligence.", more: "ISACs exist for finance, health, energy, and other sectors so organizations facing the same attackers can exchange indicators and warnings." },
  "IT": { full: "Information technology", tip: "Computers, networks, and the people who run them.", more: "IT is the department and the discipline that runs business systems. On the exam it appears in shadow IT (systems staff set up without approval) and in the contrast with operational technology." },
  "KMS": { full: "Key management service", tip: "A managed, usually cloud-hosted, service that creates, stores, rotates, and controls access to encryption keys.", more: "A KMS centralizes key lifecycle: generation, storage backed by HSMs, rotation, access policies, and audit logs. Applications call it to encrypt data instead of handling raw keys themselves. In Windows the same letters also name the Key Management Service for volume activation." },
  "LACP": { full: "Link Aggregation Control Protocol", tip: "Negotiates bundling several physical links into one logical link (802.1AX, formerly 802.3ad).", more: "LACP lets two devices agree to combine parallel links into one channel for more bandwidth and redundancy. Both ends must be configured, and the links must match in speed and duplex. If one physical link fails the bundle keeps working with the rest." },
  "LAN": { full: "Local area network", tip: "One site's network: a building, floor, or campus that one organization owns and runs.", more: "A LAN is the network inside one location, usually built from switches and Ethernet or Wi-Fi, running at high speed because the organization owns every piece of it. When a question says one office, one building, or one campus, it is describing a LAN. Anything that crosses a provider's link to reach another city is no longer a LAN." },
  "LDAP": { full: "Lightweight Directory Access Protocol", tip: "Queries a directory such as Active Directory for users and groups; TCP 389, secure 636.", more: "LDAP is how applications look up accounts, group memberships, and attributes in a directory. Plain LDAP sends binds in the clear, so LDAPS on 636 or StartTLS should be used. Kerberos handles the actual Windows logon; LDAP handles lookups." },
  "LDAPS": { full: "LDAP Secure", tip: "LDAP over TLS on TCP 636.", more: "LDAPS encrypts directory queries and the credentials used to bind. It is the secure pair for plain LDAP on 389." },
  "LTE": { full: "Long-Term Evolution", tip: "4G cellular data; the workhorse mobile broadband standard.", more: "LTE carries all-IP data at tens of megabits per second and remains the fallback under 5G. Phones, hotspots, and SD-WAN backup links use it." },
  "MAC": { full: "Media access control address, or mandatory access control", tip: "The Layer 2 hardware address of a network interface; in access control, the model where the system enforces labels.", more: "As an address, a MAC is the 48-bit identifier a switch uses to forward frames; port security limits which addresses a port accepts, and they can be spoofed. As an access control model, mandatory access control assigns classification labels that users cannot change, as in military systems and SELinux. Read the sentence to tell which is meant." },
  "MD5": { full: "Message Digest 5", tip: "A 128-bit hash that is broken: collisions can be manufactured; recognize, never recommend.", more: "MD5 was the workhorse hash of the 1990s. Because attackers can craft two different files with the same MD5, it must not be used for signatures or integrity checks. It survives only for non-security checksums." },
  "MDM": { full: "Mobile device management", tip: "Software that enrolls phones and tablets and enforces policy: passcodes, encryption, apps, remote wipe.", more: "An MDM platform lets the organization configure and secure mobile devices, corporate or personal. It can push settings, restrict apps, locate devices, and wipe a lost one, either fully or just the corporate container." },
  "MFA": { full: "Multi-factor authentication", tip: "Two or more different kinds of proof: something you know, have, are, or where you are.", more: "MFA combines factors from different categories, such as a password plus a code from a phone app. Two passwords are still one factor. It defeats stolen passwords because the attacker lacks the second factor, and it is the standard fix for account takeover in exam scenarios." },
  "MIME": { full: "Multipurpose Internet Mail Extensions", tip: "The standard that lets email carry attachments and non-text content.", more: "MIME defines how files, images, and rich text are encoded inside email. S/MIME adds signing and encryption to messages." },
  "MOA": { full: "Memorandum of agreement", tip: "A more formal, sometimes binding, statement of what parties agree to do.", more: "An MOA is a step up from a memorandum of understanding: it spells out specific commitments and responsibilities between parties." },
  "MOU": { full: "Memorandum of understanding", tip: "A non-binding statement of intent and roles between parties.", more: "An MOU records what two organizations expect from each other before or instead of a binding contract. It shows intent and shared understanding but is not enforceable the way an SLA or MSA is." },
  "MPLS": { full: "Multiprotocol Label Switching", tip: "A provider WAN that forwards by short labels instead of IP lookups, with traffic engineering and QoS.", more: "MPLS carriers put a label on each packet at the edge and switch on the label through the core, which lets them build private WANs with guaranteed performance for customers. It is reliable and expensive, and SD-WAN is often used to replace or supplement it with cheap internet links." },
  "ms": { full: "Millisecond", tip: "One thousandth of a second; latency and response times.", more: "Network latency is quoted in ms. Satellite links add 500 to 600 ms, which hurts voice and interactive traffic. Monitors also quote response time in ms." },
  "MSA": { full: "Master service agreement", tip: "The umbrella contract covering a whole vendor relationship; individual jobs hang off it.", more: "An MSA sets the general terms, liability, and payment rules once, so each new project needs only a short statement of work." },
  "MTBF": { full: "Mean time between failures", tip: "The average running time before a component fails; a reliability measure.", more: "MTBF is a statistical estimate of how long a device runs between failures. A higher MTBF means a more reliable part. It is used with MTTR to plan spares and redundancy." },
  "MTTR": { full: "Mean time to repair", tip: "The average time to fix a failure and restore service.", more: "MTTR measures how quickly you recover. Spares on site, documentation, and remote access all lower it. Together with MTBF it drives availability calculations." },
  "NAC": { full: "Network access control", tip: "Checks a device's identity and health before letting it onto the network.", more: "NAC combines 802.1X authentication with posture checks such as patch level and antivirus status, then places the device in the right VLAN or quarantines it. Agent-based NAC installs software on the endpoint; agentless NAC inspects it from the network." },
  "NAT-T": { full: "NAT traversal", tip: "Wraps IPsec in UDP 4500 so it can pass through address translation.", more: "Because NAT rewrites addresses and ESP has no ports, IPsec normally breaks behind a home router. NAT-T detects the translator and encapsulates ESP in UDP so the tunnel works." },
  "NDA": { full: "Non-disclosure agreement", tip: "A contract that keeps shared information confidential.", more: "NDAs protect trade secrets and sensitive data when vendors, partners, or new employees are given access. Violations are a legal matter, which is why they appear alongside other agreements on the exam." },
  "NGFW": { full: "Next-generation firewall", tip: "A firewall that identifies applications and users, and includes intrusion prevention.", more: "An NGFW inspects traffic beyond ports, recognizing applications such as a specific cloud service, applying user-based rules, and running IPS signatures, often with TLS inspection." },
  "NTP": { full: "Network Time Protocol", tip: "Synchronizes clocks across the network (UDP 123); wrong time breaks Kerberos, certificates, and logs.", more: "NTP keeps every device's clock aligned to a reference. Stratum 0 is the reference clock (GPS, atomic), stratum 1 servers connect to it, and each hop adds one. Kerberos fails when clocks differ by more than five minutes, certificates look expired, and logs cannot be correlated. NTS adds authentication. In the CBET course the same letters also name the National Toxicology Program; read the context." },
  "NTS": { full: "Network Time Security", tip: "Authentication and integrity for NTP so time cannot be spoofed.", more: "NTS uses TLS to set up keys and then authenticates NTP packets, defeating attackers who would shift a network's clocks to break authentication or hide their tracks." },
  "OAuth": { full: "Open Authorization", tip: "Lets a user grant an application limited access to their account on another service without sharing the password.", more: "OAuth issues access tokens with specific scopes, which is how a calendar app can read your email provider's calendar without your password. OpenID Connect adds login on top of it." },
  "OCSP": { full: "Online Certificate Status Protocol", tip: "A real-time query to the CA asking whether one certificate is revoked.", more: "Instead of downloading a whole CRL, the client asks the OCSP responder about one serial number. OCSP stapling has the web server include a recent signed answer in the TLS handshake, saving the client the lookup and protecting privacy." },
  "OS": { full: "Operating system", tip: "The software that manages hardware and runs applications: Windows, macOS, Linux, iOS, Android.", more: "The OS controls processes, memory, files, and devices. Keeping it patched and hardened is the first endpoint defense. In cloud terms, with IaaS you manage the OS and the provider manages the hardware." },
  "OSINT": { full: "Open-source intelligence", tip: "Information gathered from public sources: websites, social media, records, DNS.", more: "Attackers and penetration testers use OSINT to learn names, email formats, technologies, and physical details before an attack. It is passive reconnaissance; nothing touches the target's systems." },
  "P7B": { full: "PKCS #7 bundle", tip: "A file holding a certificate chain with no private key.", more: "P7B files carry a certificate and its intermediates so a server or client can build the trust chain. They never contain the private key." },
  "PBKDF2": { full: "Password-Based Key Derivation Function 2", tip: "Stretches a password with many hash rounds so guessing is slow.", more: "PBKDF2 hashes the password with a salt thousands of times, so each guess costs the attacker real time while a legitimate login stays fast. bcrypt, scrypt, and Argon2 do the same job with more resistance to hardware attacks." },
  "PEAP": { full: "Protected EAP", tip: "A server certificate creates a TLS tunnel and the user's password is checked inside it.", more: "PEAP is the common enterprise Wi-Fi method for username and password logins: the server proves itself with a certificate, then the client sends credentials through the encrypted tunnel." },
  "PEM": { full: "Privacy Enhanced Mail (format)", tip: "The Base64 text format for certificates and keys, with BEGIN and END lines.", more: "PEM files are readable text that can be pasted into configuration. They may hold a certificate, a chain, or a private key. DER is the same content in binary." },
  "PFX": { full: "Personal Information Exchange", tip: "A password-protected bundle holding a certificate and its private key (also .p12).", more: "PFX or PKCS #12 files move a certificate together with its private key between systems, protected by a password. Because they contain the private key they must be handled carefully." },
  "PIN": { full: "Personal identification number", tip: "A short numeric secret, a something-you-know factor.", more: "A PIN unlocks a phone, a SIM, or a smart card. A password plus a PIN is still one factor because both are things you know." },
  "PKI": { full: "Public key infrastructure", tip: "The system of certificate authorities, certificates, and revocation that makes public keys trustworthy.", more: "PKI ties a public key to an identity through a certificate signed by a certificate authority. Browsers and devices trust root CAs, which sign intermediates, which sign server and user certificates. Revocation lists and OCSP handle certificates that must be withdrawn early." },
  "POP3": { full: "Post Office Protocol version 3", tip: "Downloads mail to one device and usually deletes it from the server; TCP 110, secure 995.", more: "POP3 pulls messages to a single client and typically removes them from the server, so mail does not sync across devices. It is simple and old; IMAP is the modern choice." },
  "POP3S": { full: "POP3 Secure", tip: "POP3 over TLS on TCP 995.", more: "POP3S is the encrypted form of POP3. Use it or IMAPS instead of the plaintext ports when a client must fetch mail." },
  "PSK": { full: "Pre-shared key", tip: "One shared passphrase for everyone on a Wi-Fi network (Personal mode).", more: "A PSK is the Wi-Fi password typed into every device. It is simple but weak for organizations: everyone knows it, and revoking one person means changing it everywhere. Enterprise mode with 802.1X and RADIUS gives each user their own credentials." },
  "RA": { full: "Registration authority", tip: "The part of a PKI that verifies identities before the CA signs.", more: "The RA checks that an applicant is who they claim, then passes the approved request to the certificate authority." },
  "RADIUS": { full: "Remote Authentication Dial-In User Service", tip: "The AAA server behind Wi-Fi Enterprise, VPNs, and 802.1X; UDP 1812 and 1813.", more: "A RADIUS server checks credentials for network access devices (switches, APs, VPN gateways) and tells them what the user is allowed. It encrypts only the password, uses UDP, and combines authentication and authorization, which is why TACACS+ is preferred for device administration." },
  "RAID": { full: "Redundant array of independent disks", tip: "Combining disks for speed, capacity, or fault tolerance: 0 stripe, 1 mirror, 5 stripe with parity, 6 double parity, 10 mirrored stripes.", more: "RAID 0 stripes data across disks for speed with no redundancy; one failure loses everything. RAID 1 mirrors two disks. RAID 5 stripes with one parity block and survives one disk failure (three disks minimum). RAID 6 has two parity blocks and survives two failures (four disks). RAID 10 mirrors pairs then stripes, needing four disks. RAID is availability, not backup." },
  "RAM": { full: "Random-access memory", tip: "The working memory that holds running programs and data; lost at power off.", more: "RAM speed and capacity limit how much a system can do at once. Because it is volatile, forensics collects it first (order of volatility) before the machine is powered down." },
  "RAT": { full: "Remote access trojan", tip: "Malware that opens a back door so an attacker can control the machine.", more: "A RAT hides as legitimate software and gives the attacker remote control: files, keystrokes, camera, and a foothold for more attacks. Endpoint protection and egress filtering detect and contain it." },
  "RBAC": { full: "Role-based access control", tip: "Permissions are assigned to roles, and users get roles.", more: "RBAC simplifies administration: a new accountant gets the accountant role rather than dozens of individual permissions. It is the most common model in business systems." },
  "RC4": { full: "Rivest Cipher 4", tip: "A fast stream cipher used in WEP and old TLS; broken and deprecated.", more: "RC4's weaknesses are why WEP fell and why TLS banned it. It appears on the exam only as an example of an algorithm to replace." },
  "RDP": { full: "Remote Desktop Protocol", tip: "Microsoft's remote graphical desktop on TCP 3389.", more: "RDP gives a full Windows desktop over the network. Exposed directly to the internet it is a frequent attack target, so it should sit behind a VPN or gateway with MFA and network level authentication." },
  "RFID": { full: "Radio-frequency identification", tip: "Tags read by radio for badges, inventory, and asset tracking.", more: "RFID badges open doors, and RFID tags track assets. Because tags answer any reader, cloning is possible, so high-security doors combine a badge with a PIN or biometric." },
  "RPO": { full: "Recovery point objective", tip: "The maximum acceptable data loss, measured in time.", more: "An RPO of one hour means backups or replication must run at least hourly, because after a disaster you may lose everything since the last copy. It drives how often you back up." },
  "RSA": { full: "Rivest, Shamir, Adleman", tip: "The classic public-key algorithm for encryption and digital signatures.", more: "RSA uses a public and private key pair based on the difficulty of factoring large numbers. It encrypts session keys, signs certificates, and authenticates SSH users. Keys of 2048 bits or more are required today; ECC gives the same strength with shorter keys." },
  "RTO": { full: "Recovery time objective", tip: "The maximum acceptable time to restore a service after failure.", more: "An RTO of four hours means the service must be back within four hours. It drives what recovery site you need: a hot site restores in minutes, a cold site in days." },
  "RTOS": { full: "Real-time operating system", tip: "An operating system that guarantees responses within strict time limits, used in embedded and control devices.", more: "RTOS-based devices such as medical equipment, vehicle controllers, and industrial sensors prioritize timing over features and are hard to patch, so they need network isolation." },
  "RTP": { full: "Real-time Transport Protocol", tip: "Carries the actual voice and video packets of a call, over UDP.", more: "After SIP sets up a call, RTP streams the audio and video with sequence numbers and timestamps so the receiver can play them in order and measure jitter. SRTP is the encrypted version." },
  "SaaS": { full: "Software as a service", tip: "Complete applications delivered over the web, such as email and office suites.", more: "With SaaS you log in and use the software; the provider runs everything. It is the model with the least customer responsibility and the least control." },
  "SAE": { full: "Simultaneous authentication of equals", tip: "The WPA3 Personal handshake that resists offline password guessing.", more: "SAE is a password-authenticated key exchange, sometimes called Dragonfly. Both sides prove they know the passphrase without ever sending anything an eavesdropper could attack offline, and each session gets a fresh key. It is why WPA3 Personal is safe with a weaker passphrase than WPA2 would be." },
  "SAML": { full: "Security Assertion Markup Language", tip: "An XML standard for passing authentication between an identity provider and a web application (enterprise SSO).", more: "With SAML the application sends the user to the identity provider, which authenticates and returns a signed assertion listing who the user is and their attributes. It is the classic protocol for enterprise web single sign-on and federation." },
  "SAN": { full: "Subject alternative name, or storage area network", tip: "On a certificate, the list of hostnames it covers; in infrastructure, a dedicated block-storage network.", more: "A certificate's SAN field lists every hostname it is valid for, which is how one certificate covers www and mail. A storage area network gives servers block-level access to disk arrays over Fibre Channel or iSCSI. Read the context." },
  "SASE": { full: "Secure access service edge", tip: "SD-WAN networking plus cloud-delivered security (firewall, web gateway, ZTNA, CASB) as one service.", more: "SASE moves the security stack into the cloud close to users and branches, so remote workers and sites get the same policy without backhauling traffic to a data center. It bundles SD-WAN with the security functions that SSE describes." },
  "SCADA": { full: "Supervisory control and data acquisition", tip: "Systems that monitor and control industrial processes such as power, water, and manufacturing.", more: "SCADA gathers data from field sensors and sends commands to controllers over networks that were designed long before internet threats. It runs on old software, cannot tolerate downtime, and must be isolated from the corporate network and the internet." },
  "SCAP": { full: "Security Content Automation Protocol", tip: "Standard formats that let tools check systems against security benchmarks automatically.", more: "SCAP bundles standards such as CVE, CVSS, and configuration checklists so scanners can measure compliance and vulnerabilities consistently across vendors." },
  "SD-WAN": { full: "Software-defined wide area network", tip: "Steers traffic across several cheap links (broadband, LTE, MPLS) by policy from a central controller.", more: "SD-WAN puts an appliance at each site, builds encrypted tunnels over whatever links exist, and lets a central controller choose the best path per application based on measured loss and latency. It cuts cost versus MPLS and makes cloud access direct rather than backhauled." },
  "SDLC": { full: "Software development life cycle", tip: "The phases of building software: plan, design, code, test, deploy, maintain.", more: "Secure SDLC builds security into each phase rather than testing for it at the end: threat modeling in design, code review and static analysis in development, dynamic testing before release, and patching in maintenance." },
  "SDN": { full: "Software-defined networking", tip: "Separates the control plane (decisions) from the data plane (forwarding) and centralizes control.", more: "In SDN a controller programs many switches through APIs instead of each device running its own configuration. The control plane decides paths; the data plane forwards packets; the management plane is where administrators talk to the controller. It enables automation and fast policy changes." },
  "SFTP": { full: "SSH File Transfer Protocol", tip: "File transfer inside an SSH session, TCP 22.", more: "SFTP is not FTP with encryption bolted on; it is a separate protocol carried over SSH. It uses one port, 22, which makes it firewall friendly, and it is the usual secure replacement for FTP." },
  "SHA": { full: "Secure Hash Algorithm", tip: "The family of hash functions: SHA-1 (deprecated), SHA-2 (SHA-256, the standard), SHA-3.", more: "Hashes turn any input into a fixed-length fingerprint. SHA-256 and the SHA-2 family are current; SHA-1 is deprecated because collisions have been demonstrated; SHA-3 is a newer alternative design." },
  "SHA-1": { full: "Secure Hash Algorithm 1", tip: "A 160-bit hash, deprecated because collisions have been found.", more: "SHA-1 should not be used for certificates or signatures. Browsers reject SHA-1 certificates. It appears on the exam as the deprecated choice next to SHA-256." },
  "SHA-2": { full: "Secure Hash Algorithm 2", tip: "The current hash family, including SHA-256 and SHA-512.", more: "SHA-2 is the standard for certificates, signatures, and integrity checks. SHA-256 is its most common member." },
  "SHA-256": { full: "Secure Hash Algorithm 256-bit", tip: "The standard hash today: a 256-bit fingerprint of any input.", more: "SHA-256 is used in TLS certificates, code signing, file integrity, and password storage (with salting and stretching). Any change to the input changes the output completely, which is what makes it useful for integrity." },
  "SHA-3": { full: "Secure Hash Algorithm 3", tip: "A newer hash standard with a different internal design from SHA-2.", more: "SHA-3 was standardized as an alternative in case weaknesses appear in SHA-2. Both are acceptable; SHA-2 remains more common." },
  "SIEM": { full: "Security information and event management", tip: "Collects logs from everything, correlates them, and raises alerts.", more: "A SIEM ingests syslog, Windows events, firewall and IDS logs, normalizes them, and looks for patterns across sources, such as one account failing logins on many hosts. It provides dashboards, alerting, and the searchable history investigators need." },
  "SIP": { full: "Session Initiation Protocol", tip: "Sets up and tears down voice and video calls; port 5060, or 5061 with TLS.", more: "SIP is the signaling protocol for VoIP: it registers phones, rings the far end, and negotiates the media session. The voice itself travels in RTP. Because SIP often needs many ports and passes through NAT, VoIP problems frequently trace to firewalls or NAT helpers." },
  "SLA": { full: "Service level agreement", tip: "The contract stating measurable service commitments, such as 99.9% uptime.", more: "An SLA defines what a provider promises (availability, response time, repair time) and the penalties for missing it. Guaranteed uptime from the ISP is an SLA. Internal IT also uses SLAs for help desk response." },
  "SLE": { full: "Single loss expectancy", tip: "The cost of one occurrence of a risk: asset value times exposure factor.", more: "SLE puts a dollar figure on one incident. Multiply it by the annualized rate of occurrence to get the yearly expected loss, which is what you compare against the cost of a control." },
  "SMB": { full: "Server Message Block", tip: "Windows file and printer sharing on TCP 445.", more: "SMB is the protocol behind mapped drives and shared printers. Version 1 is insecure and should be disabled; versions 2 and 3 add signing and encryption. Blocking 445 at the perimeter stops most worm-style spread." },
  "SMS": { full: "Short Message Service", tip: "Text messages; used for one-time codes and also a phishing channel (smishing).", more: "SMS codes are a common but weak second factor because SIM swapping and interception can steal them. Smishing is phishing by text message." },
  "SMTP": { full: "Simple Mail Transfer Protocol", tip: "Sends email between servers on TCP 25; clients submit on 587 with TLS.", more: "SMTP moves mail toward its destination. Server-to-server delivery uses port 25; client submission uses 587 (or legacy 465) with authentication and TLS. Receiving and reading mail uses POP3 or IMAP, not SMTP." },
  "SMTPS": { full: "SMTP Secure", tip: "SMTP with TLS, port 465 (implicit) or 587 with STARTTLS.", more: "SMTPS protects mail submission between a client and its mail server. Port 587 with STARTTLS is the modern standard; 465 is the older implicit-TLS port." },
  "SNMP": { full: "Simple Network Management Protocol", tip: "Polls and receives alerts from network devices (UDP 161 polls, 162 traps).", more: "An SNMP manager polls agents on devices for values in their MIB, such as interface counters and CPU load, and agents send traps when something happens. Versions 1 and 2c use a plaintext community string; version 3 adds authentication and encryption and is the only version to recommend." },
  "SOW": { full: "Statement of work", tip: "Defines one specific piece of work: deliverables, timeline, and price.", more: "A SOW sits under an MSA and describes a single project in detail. A work order is the smaller cousin for routine tasks." },
  "SPF": { full: "Sender Policy Framework", tip: "A DNS TXT record listing which servers may send mail for a domain.", more: "Receiving servers check the sender's IP against the domain's SPF record and reject or flag mail from elsewhere. It is one of the three email authentication records with DKIM and DMARC." },
  "SQL": { full: "Structured Query Language", tip: "The language used to query databases; also the name of the servers on TCP 1433 (Microsoft) and 3306 (MySQL).", more: "SQL is how applications read and write relational databases. On the exam it appears as the database server ports and, in security, as SQL injection, where untrusted input is pasted into a query and changes what it does." },
  "SRTP": { full: "Secure Real-time Transport Protocol", tip: "Encrypted RTP for voice and video.", more: "SRTP adds encryption and authentication to RTP media streams so calls cannot be eavesdropped or altered. Pair it with SIP over TLS for a fully protected call." },
  "SSH": { full: "Secure Shell", tip: "Encrypted remote command-line access and file transfer on TCP 22; replaces Telnet and FTP.", more: "SSH authenticates with passwords or keys and encrypts the whole session. SFTP and SCP ride on it for file copies. Any question about managing a switch or server securely from the command line wants SSH." },
  "SSID": { full: "Service set identifier", tip: "The Wi-Fi network name that access points broadcast and clients join.", more: "The SSID is the human-readable network name, up to 32 characters. One AP can advertise several SSIDs, each mapped to a different VLAN, for example staff and guest. Hiding the SSID stops it appearing in scan lists but is not security, because clients still send it in the clear when they connect." },
  "SSL": { full: "Secure Sockets Layer", tip: "The predecessor of TLS; every version is deprecated.", more: "SSL 2.0 and 3.0 are broken and must be disabled. People still say SSL certificate, but the protocol in use is TLS." },
  "SSO": { full: "Single sign-on", tip: "Log in once and reach many systems without signing in again.", more: "SSO lets an identity provider vouch for the user to every application, using protocols such as SAML, OAuth, and OpenID Connect. It improves convenience and lets one strong login with MFA protect everything, at the cost of that login becoming a high-value target." },
  "SSRF": { full: "Server-side request forgery", tip: "Makes the web server itself fetch a URL the attacker supplies, often reaching internal systems.", more: "In SSRF the attacker feeds a server a URL and the server requests it, letting the attacker reach internal addresses and cloud metadata services that are unreachable from outside. Allow-listing destinations is the fix." },
  "SY0-701": { full: "CompTIA Security+ exam SY0-701", tip: "The current version of the Security+ certification exam.", more: "SY0-701 covers general security concepts, threats and vulnerabilities, architecture, operations, and governance. It has up to 90 questions in 90 minutes with a passing score of 750 on a 100 to 900 scale." },
  "TACACS+": { full: "Terminal Access Controller Access-Control System Plus", tip: "Cisco's AAA protocol for device administration on TCP 49; encrypts the whole payload and separates authentication from authorization.", more: "TACACS+ is used to control who can log in to routers and switches and which commands they may run. Compared with RADIUS it uses TCP, encrypts the entire packet, and handles authorization command by command, which suits administrative access rather than user network access." },
  "TCP": { full: "Transmission Control Protocol", tip: "Reliable, ordered, connection-based transport: three-way handshake, acknowledgments, retransmission.", more: "TCP sets up a connection with a SYN, SYN-ACK, ACK handshake, numbers every segment, acknowledges what arrives, and resends what does not. That reliability costs overhead, so it suits web pages, email, and file transfer rather than live voice. Port numbers at Layer 4 identify which application on the host the data is for." },
  "TFTP": { full: "Trivial File Transfer Protocol", tip: "Bare-bones UDP 69 file transfer with no login, used for firmware and config files.", more: "TFTP has no authentication and no directory listing, so it is only for trusted networks: pushing switch firmware, backing up configurations, and network booting (PXE). It should be blocked at the perimeter." },
  "TKIP": { full: "Temporal Key Integrity Protocol", tip: "WPA's per-packet keying scheme; deprecated.", more: "TKIP wrapped the old RC4 cipher with changing keys so WEP hardware could be patched. It is now considered broken and WPA2 with AES-CCMP or WPA3 should be used instead." },
  "TLS": { full: "Transport Layer Security", tip: "The encryption layer under HTTPS and most secure protocols; use 1.2 or 1.3.", more: "TLS authenticates the server with a certificate, agrees session keys, and then encrypts the connection. It replaced SSL, whose versions are all deprecated. TLS 1.0 and 1.1 are also retired. It works at the presentation and session layers in OSI terms and protects web, mail, LDAP, and VPN traffic." },
  "TOC": { full: "Time of check", tip: "The moment a program verifies a condition; in a race condition, before it acts on it.", more: "A time-of-check to time-of-use flaw lets an attacker change something between the check and the use, for example swapping a file after it was validated but before it was opened." },
  "TOU": { full: "Time of use", tip: "The moment a program acts on a condition it checked earlier.", more: "TOC/TOU race conditions exploit the gap between checking and using. The defense is to make the check and the use one atomic operation." },
  "TPM": { full: "Trusted Platform Module", tip: "A security chip on the motherboard that stores keys and measurements; required for BitLocker and Windows 11.", more: "The TPM holds encryption keys that never leave the chip and records boot measurements so it can refuse to release keys if the firmware or boot loader changed. Full-disk encryption keys, device identity certificates, and attestation all rely on it." },
  "TV": { full: "Television", tip: "A display or broadcast receiver; smart TVs are IoT devices.", more: "Cable TV shares the coax with the cable modem. Smart TVs join the network and should be segmented like other IoT." },
  "UBA": { full: "User behavior analytics", tip: "Baselines what each user normally does and flags deviations.", more: "UBA, or UEBA including entities, learns normal login times, locations, and data volumes and alerts when an account suddenly behaves differently, which catches stolen credentials and insiders." },
  "UEFI": { full: "Unified Extensible Firmware Interface", tip: "Modern firmware that replaces BIOS: GPT disks, Secure Boot, mouse-driven setup.", more: "UEFI boots from GPT disks of any size, verifies boot loaders with Secure Boot, and offers a graphical setup. A compatibility mode (CSM) boots legacy BIOS-style systems. Windows 11 requires UEFI with Secure Boot and a TPM." },
  "UPS": { full: "Uninterruptible power supply", tip: "A battery unit that keeps equipment running through a power cut and conditions the power.", more: "A UPS sits between the wall and the equipment, taking over instantly when power fails and giving time to shut down or for a generator to start. It is sized in VA or watts against the load for the runtime needed. In medical settings a UPS covers the transfer gap to emergency power." },
  "URL": { full: "Uniform resource locator", tip: "A web address such as https://www.example.com/page.", more: "The URL names the protocol, host, port, path, and query. URL filtering blocks sites by address or category; attackers hide malicious URLs behind look-alike domains and shortened links." },
  "USB": { full: "Universal Serial Bus", tip: "The standard port for peripherals, storage, and charging.", more: "USB versions set speed: 2.0 at 480 Mbps, 3.0 at 5 Gbps, 3.1 at 10 Gbps, 3.2 at 20 Gbps, USB4 at 40 Gbps. Connectors include A, B, mini, micro, and the reversible C. Unknown USB drives are a malware vector, which DLP and device control address." },
  "UTM": { full: "Unified threat management", tip: "One appliance bundling firewall, IDS/IPS, antivirus, content filtering, and VPN.", more: "UTM devices give small and mid-sized organizations a full security stack in one box. The trade-off is that one device becomes a bottleneck and a single point of failure." },
  "VLAN": { full: "Virtual local area network", tip: "A logical LAN on a switch: ports in different VLANs are separate broadcast domains.", more: "A VLAN splits one physical switch into several logical switches. Ports in VLAN 10 cannot talk to ports in VLAN 20 without a router or Layer 3 switch, which contains broadcasts and separates traffic such as voice, data, and guests. Trunk links carry many VLANs between switches using 802.1Q tags. A native VLAN is the untagged one on a trunk, and a voice VLAN lets a phone tag its traffic while the PC behind it stays untagged." },
  "VM": { full: "Virtual machine", tip: "A complete computer running as software on a hypervisor.", more: "A VM has its own operating system and virtual hardware but shares the physical host with others. Type 1 hypervisors run on bare metal; type 2 run on a host OS. VM escape, where code in a guest reaches the host, is the serious virtualization vulnerability; VM sprawl is the management one." },
  "VPN": { full: "Virtual private network", tip: "An encrypted tunnel across an untrusted network such as the internet.", more: "A VPN makes a remote user or site appear to be on the private network by encrypting traffic between the endpoints. Site-to-site VPNs join offices, usually with IPsec; remote-access VPNs connect individual users with IPsec or TLS clients. Split tunneling sends only corporate traffic through the tunnel; full tunneling sends everything." },
  "WAF": { full: "Web application firewall", tip: "A firewall that understands HTTP and blocks attacks on web applications such as SQL injection and XSS.", more: "A WAF sits in front of web servers and inspects requests and responses at the application layer. It is the control for web attacks that a network firewall, which only sees ports and addresses, cannot recognize." },
  "WAN": { full: "Wide area network", tip: "Connects LANs across cities or countries, usually over links leased from a provider.", more: "A WAN joins sites that are far apart. Because the organization cannot run its own cable between cities, it rents circuits or internet connections from a carrier, which is why WAN links are slower and cost per month. The internet is the largest WAN. Routers sit at the edge of each site to send traffic across the WAN." },
  "WEP": { full: "Wired Equivalent Privacy", tip: "The original Wi-Fi encryption, broken in minutes; never use it.", more: "WEP used the RC4 cipher with short, badly managed keys, and tools can recover the key from captured traffic in minutes. Any question describing WEP wants you to replace it with WPA2 or WPA3." },
  "Wi-Fi": { full: "Wireless fidelity", tip: "The trade name for IEEE 802.11 wireless networking.", more: "Wi-Fi is the brand the Wi-Fi Alliance gives to interoperable 802.11 equipment. Generations are numbered: Wi-Fi 4 is 802.11n, Wi-Fi 5 is 802.11ac, Wi-Fi 6 and 6E are 802.11ax (6E adds the 6 GHz band), and Wi-Fi 7 is 802.11be. Bands are 2.4 GHz (range, interference), 5 GHz (speed, more channels), and 6 GHz." },
  "WO": { full: "Work order", tip: "A short authorization for one specific job.", more: "Work orders define individual tasks under a broader agreement, such as installing ten access points on a given date." },
  "WPA": { full: "Wi-Fi Protected Access", tip: "The interim fix for WEP that used TKIP; deprecated.", more: "WPA kept WEP-era hardware working by adding per-packet keys with TKIP. It was a stopgap until WPA2 brought AES and is now considered insecure." },
  "WPA2": { full: "Wi-Fi Protected Access 2", tip: "Wi-Fi security using AES with CCMP; still common and acceptable.", more: "WPA2 replaced TKIP with AES-CCMP encryption. Personal mode uses a pre-shared passphrase; Enterprise mode authenticates each user through 802.1X and RADIUS. Its weakness is that a captured handshake can be attacked offline with password guessing, which WPA3 fixes." },
  "WPA3": { full: "Wi-Fi Protected Access 3", tip: "The current Wi-Fi security standard: SAE in Personal mode, stronger encryption, protected management frames.", more: "WPA3 Personal replaces the pre-shared key handshake with SAE (simultaneous authentication of equals), which stops offline password cracking and adds forward secrecy. Enterprise mode still uses 802.1X. Protected management frames are mandatory, blocking deauthentication attacks." },
  "XDR": { full: "Extended detection and response", tip: "EDR extended across endpoints, network, cloud, and email into one correlated view.", more: "XDR pulls detections from many sources together so an attack that touches email, an endpoint, and a server shows as one incident." },
  "XML": { full: "Extensible Markup Language", tip: "A text format for structured data, used by SAML, HL7 version 3, and many configuration files.", more: "XML wraps data in nested tags. It is verbose but readable, and its parsers can be attacked (XML injection, external entity attacks), which is why input validation matters." },
  "XSS": { full: "Cross-site scripting", tip: "An attacker's script runs in other users' browsers because a site echoes untrusted input.", more: "In XSS the attacker stores or reflects script through a web page so that it executes in the victim's browser, stealing sessions or acting as the user. Input validation and output encoding are the defenses." }
};
// Uppercase words in the course text that are not acronyms (emphasis, registry key names, model numbers, formula symbols).
FRA.acronymIgnore = ["BEST","FIRST","LEAST","MOST","MUST","NEXT","NOT","OR"];
